package com.example.auth;

import java.security.SecureRandom;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Issues and validates session identifiers.
 *
 * <p>Identifiers are 32 characters of lower-case hexadecimal - 128 bits from
 * {@link SecureRandom#getStrongInstance()} - generated by this code at the moment a sign-in is
 * verified. They are never accepted from a caller as an input to sign-in, never derived from
 * anything the caller supplies, and never predictable: there is no counter, timestamp, MAC address
 * or hash-of-the-account involved.
 *
 * <p>Validity is decided only by presence in this table, which is server-side state. A
 * well-formed-but-unknown identifier is simply not valid; there is no self-contained token to trust
 * and nothing to parse, so a caller cannot construct one.
 *
 * <p><b>Atomicity.</b> Issue, validate-and-touch, revoke and capacity bookkeeping all happen under
 * one lock on the map. Expired entries are dropped inside the same critical section as a validation,
 * so an expired session cannot be validated by one thread while another is still touching it.
 *
 * <p><b>Bounded.</b> At most {@code maxActiveSessions} identifiers exist; when the table is full the
 * oldest-expiring entry is evicted and a fresh issue is refused only if no entry can be reclaimed.
 * Refusing to issue (rather than dropping capacity limits) is what keeps memory bounded under a
 * script that signs in continuously.
 *
 * <p><b>Residual risk, documented in the README:</b> the table is in-process. Behind more than one
 * node, a session issued by one node is unknown to another; a deployment needs a shared session
 * store. In-memory identifiers are also not protected at rest - they live in the heap, which is why
 * the README lists heap dumping as a residual risk and why the transport requirements below apply.
 *
 * <p><b>Cookie contract for the caller.</b> This component returns the identifier only; the caller
 * must set it as a cookie with {@code HttpOnly}, {@code Secure}, {@code SameSite=Strict}, a
 * {@code Path} no broader than the application root, and an {@code Expires}/{@code Max-Age} no
 * longer than {@link #ttlSeconds()}. It must not place the identifier in a URL, in a response body,
 * in a log line, or in a {@code Referrer-Policy}-permitted link. A helper that builds the
 * {@code Set-Cookie} value is provided in {@link #cookieDirectiveFor(String, String, String, boolean)}
 * so the flags cannot be forgotten by an integrator; it emits {@code HttpOnly}, {@code Secure} and
 * {@code SameSite=Strict} on a TLS request and returns {@code null} for a plaintext one, so a caller
 * that cannot say whether the connection is TLS gets no cookie at all rather than one that could
 * travel in clear text. The four-argument form is the only one an integrator should reach for: the
 * three-argument overload is a convenience for code that has already proven it is on TLS, and it
 * asserts {@code secureTransport = true} on the caller's behalf.
 */
final class SessionTokenStore {

    /** Hex characters: 32 of them encode 128 bits. */
    static final int TOKEN_HEX_LENGTH = 32;

    private static final long MIN_EVICTION_GRACE_MILLIS = 1_000L;

    private final SecureRandom random;
    private final int ttlSeconds;
    private final int maxActiveSessions;
    private final TimeSource time;
    private final LinkedHashMap<String, Long> expiresAtMillis = new LinkedHashMap<>();

    private long issuedCount;
    private long evictedCount;

    SessionTokenStore(SecureRandom random, int ttlSeconds, int maxActiveSessions, TimeSource time) {
        this.random = random;
        this.ttlSeconds = ttlSeconds;
        this.maxActiveSessions = maxActiveSessions;
        this.time = time;
    }

    /**
     * Issues a new identifier.
     *
     * @return the identifier, or {@code null} when capacity is exhausted and nothing could be
     *     reclaimed. The caller must then fail the sign-in: issuing beyond capacity is not an
     *     option, and neither is silently evicting a live user's session to make room.
     */
    synchronized String issue() {
        long now = time.nowMillis();
        dropExpiredLocked(now);
        if (expiresAtMillis.size() >= maxActiveSessions) {
            if (!evictOldestExpiringLocked(now)) {
                return null;
            }
            evictedCount++;
        }
        String token = newToken();
        expiresAtMillis.put(token, now + ttlSeconds * 1000L);
        issuedCount++;
        return token;
    }

    /**
     * Validates an identifier and slides its expiry on success. Validity is presence in this table
     * and nothing else.
     *
     * <p>The shape check runs <em>first</em>, outside the lock. Everything a caller can send arrives
     * unauthenticated, and a table scan on the far side of that check would let anyone holding a
     * keyboard convert the expiry sweep into a cost that scales with the deployment's session cap
     * (100&nbsp;000 entries) rather than with the traffic they can actually generate. The sweep is
     * therefore reached only by a string that is already the right shape - i.e. one that is far more
     * likely to be a real identifier than an attacker's first probe.
     */
    synchronized boolean isValid(String candidate) {
        if (candidate == null || candidate.length() != TOKEN_HEX_LENGTH || !isHex(candidate)) {
            return false;
        }
        long now = time.nowMillis();
        dropExpiredLocked(now);
        // The lookup is a hash probe: no byte-by-byte comparison against a stored identifier ever
        // happens, so there is nothing for a timing measurement to follow. Guessing is ruled out by
        // the 128-bit space, not by comparison timing.
        Long expiry = expiresAtMillis.get(candidate);
        if (expiry == null || expiry <= now) {
            return false;
        }
        expiresAtMillis.put(candidate, now + ttlSeconds * 1000L);
        return true;
    }

    /** Revokes an identifier. Idempotent; unknown identifiers are ignored. */
    synchronized void revoke(String candidate) {
        if (candidate == null || candidate.length() != TOKEN_HEX_LENGTH) {
            return;
        }
        expiresAtMillis.remove(candidate);
    }

    /** Number of live identifiers, after dropping expired ones. */
    synchronized int activeCount() {
        dropExpiredLocked(time.nowMillis());
        return expiresAtMillis.size();
    }

    int ttlSeconds() {
        return ttlSeconds;
    }

    int maxActiveSessions() {
        return maxActiveSessions;
    }

    synchronized long issuedCount() {
        return issuedCount;
    }

    synchronized long evictedCount() {
        return evictedCount;
    }

    synchronized void clear() {
        expiresAtMillis.clear();
    }

    /**
     * Convenience form for a caller that has already established the request is on TLS.
     *
     * <p>It asserts {@code secureTransport = true}, so on a plaintext request the browser discards
     * the cookie rather than the session travelling in clear text - the failure is a lost sign-in, not
     * an exposure. Integrators who cannot prove the transport should call the four-argument form and
     * pass what they actually know.
     *
     * @param candidate the identifier returned by {@link AuthResult#sessionId()}
     * @param cookieName must be a bare token: {@code [A-Za-z0-9_-]{1,64}}
     * @param path must be an absolute path of at most 128 characters, no control characters, no
     *     comma, semicolon or CR/LF
     * @return the directive, or {@code null} when any input is unusable
     */
    public String cookieDirectiveFor(String candidate, String cookieName, String path) {
        return cookieDirectiveFor(candidate, cookieName, path, true);
    }

    /**
     * Builds the {@code Set-Cookie} value for a session identifier, with the flags an integrator is
     * most likely to forget.
     *
     * <p>{@code Secure} is included only when {@code secureTransport} is {@code true}. A caller that
     * cannot say whether the request arrived over TLS gets no directive at all rather than a
     * cookie that could travel in clear text; that is the fail-closed choice.
     *
     * @param candidate the identifier returned by {@link AuthResult#sessionId()}
     * @param cookieName must be a bare token: {@code [A-Za-z0-9_-]{1,64}}
     * @param path must be an absolute path of at most 128 characters, no control characters, no
     *     comma, semicolon or CR/LF
     * @param secureTransport whether the request arrived over TLS; {@code false} yields {@code null}
     * @return the directive, or {@code null} when any input is unusable or the transport is not TLS
     */
    public String cookieDirectiveFor(String candidate, String cookieName, String path, boolean secureTransport) {
        if (!secureTransport) {
            return null;
        }
        if (candidate == null || !isHex(candidate)) {
            return null;
        }
        if (candidate.length() != TOKEN_HEX_LENGTH) {
            return null;
        }
        if (!isCookieName(cookieName)) {
            return null;
        }
        if (!isCookiePath(path)) {
            return null;
        }
        return cookieName + "=" + candidate
                + "; Path=" + path
                + "; Max-Age=" + ttlSeconds
                + "; HttpOnly; SameSite=Strict; Secure";
    }

    private static boolean isCookieName(String name) {
        if (name == null || name.isEmpty() || name.length() > 64) {
            return false;
        }
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            boolean allowed = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
                    || c == '_' || c == '-';
            if (!allowed) {
                return false;
            }
        }
        return true;
    }

    private static boolean isCookiePath(String path) {
        if (path == null || path.length() < 1 || path.length() > 128 || path.charAt(0) != '/') {
            return false;
        }
        for (int i = 0; i < path.length(); i++) {
            char c = path.charAt(i);
            if (c <= 0x20 || c == 0x7f || c == ';' || c == ',' || c == '"' || c == '\\') {
                return false;
            }
        }
        return true;
    }

    private static boolean isHex(String value) {
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) {
                return false;
            }
        }
        return true;
    }

    private String newToken() {
        byte[] raw = new byte[TOKEN_HEX_LENGTH / 2];
        random.nextBytes(raw);
        StringBuilder out = new StringBuilder(TOKEN_HEX_LENGTH);
        for (byte b : raw) {
            out.append(Character.forDigit((b >> 4) & 0xf, 16));
            out.append(Character.forDigit(b & 0xf, 16));
        }
        return out.toString();
    }

    private void dropExpiredLocked(long now) {
        Iterator<Map.Entry<String, Long>> it = expiresAtMillis.entrySet().iterator();
        while (it.hasNext()) {
            if (it.next().getValue() <= now) {
                it.remove();
            }
        }
    }

    /**
     * Reclaims one entry when the table is full, choosing the identifier that expires soonest.
     *
     * <p>Only entries that are at least {@value #MIN_EVICTION_GRACE_MILLIS} old are eligible, so a
     * session that was just issued to a real user is not dropped by the next sign-in.
     */
    private boolean evictOldestExpiringLocked(long now) {
        String victim = null;
        long best = Long.MAX_VALUE;
        long ttlMillis = ttlSeconds * 1000L;
        for (Map.Entry<String, Long> entry : expiresAtMillis.entrySet()) {
            long expiry = entry.getValue();
            // Age, not expiry: an entry issued ttlMillis before its expiry was issued at
            // "expiry - ttlMillis". Deriving this wrongly makes every entry look ancient, which
            // turns the capacity limit into "disconnect whoever signed in earliest" instead of
            // "refuse a new session" - so saturating the table would log users out on demand.
            long ageMillis = now - (expiry - ttlMillis);
            if (ageMillis < MIN_EVICTION_GRACE_MILLIS) {
                continue;
            }
            if (expiry < best) {
                best = expiry;
                victim = entry.getKey();
            }
        }
        if (victim == null) {
            return false;
        }
        expiresAtMillis.remove(victim);
        return true;
    }

}
